"""Manual manuscript for the finance book.

This file is the source of truth for the public book. Do not generate prose from
the PDF/OCR draft. Chapters are written by hand, one by one.
"""


def ch(num, part, title, desc, lead, sections, summary, quiz):
    return {
        "num": num,
        "part": part,
        "title": title,
        "desc": desc,
        "lead": lead,
        "sections": sections,
        "summary": summary,
        "quiz": quiz,
    }


def p(text):
    return f"<p>{text}</p>"


def callout(title, body):
    return f'<div class="callout callout--note reveal"><span class="callout__title">{title}</span><p>{body}</p></div>'


PART_1 = "第一部分 · 金融世界的底层结构"
PART_2 = "第二部分 · A 股市场与交易机器"
PART_3 = "第三部分 · 收益、风险与投资评价"
PART_4 = "第四部分 · 量化研究从因子开始"
PART_5 = "第五部分 · 量化行业、个人路线与实践"


