            ("最新价为什么不等于公司真实价值?", "它只是最近一笔成交的价格,会受流动性、情绪、消息和单笔订单的影响,而估值还要看利润、资产、行业、利率和风险偏好,它代替不了完整体检。"),
            ("为什么日 K 线会丢失信息?", "它把一天成千上万笔交易压缩成开高低收四个价和成交量,盘中的路径、拉扯过程和排队细节全都被压掉了。"),
            ("复权数据为什么不能直接拿来模拟成交?", "复权是为了让历史收益可比而事后调整出来的价格,并不等于当时市场上真实可成交的价格,模拟成交要用当时真实价格口径。"),
            ("量化读取行情数据时最该先问什么?", "这条数据在交易当时是否可见、价格用的是什么复权口径、停牌和缺失怎么表示、供应商的处理规则是否一致。"),
