                    "这能解释一个让新手困惑的日常现象:有时盘面上几千只股票绿油油一片,指数却没跌多少——多半是几只大权重股在硬扛;也有时指数跌得很难看,你手里的小股票却没怎么跌——因为砸盘的正是那几只大块头。记住,指数是加权平均,不是所有股票的简单平均;它先听见大公司的声音。"
