        "量化系统最容易被误解成一台只管赚钱的机器。但真正成熟的系统,还要能回答一连串“如果”: 市场突然变了怎么办? 模型连续失效怎么办? 成交成本暴涨怎么办? 某个行业暴露过高怎么办? 风险控制不是保守派在旁边拖后腿,而是让策略有资格活到长期优势兑现的那套机制。这一章就把这套机制拆开看。",
