                    "第四种:流动性冲击。多头和空头都需要交易,市场流动性一变差,滑点上升,平仓都困难。第五种:监管或交易规则变化,影响股指期货、融券或程序化交易——游戏规则的修改,从来不会提前征求策略的意见。"
