        "金融资料遍地都是,质量差距也巨大:券商研报可能有启发,学术论文可能严谨,基金月报可能贴近真实产品,网络文章可能讲得通俗。但无论作者多权威,只看结论都是危险的。读一份量化资料的正确顺序是:它到底研究什么问题,用了什么数据,有没有偷看未来,跟谁比,成本怎么扣,样本外怎么样,结论落到交易上还成不成立。把这套顺序养成本能,你就很难再被漂亮 PPT 带走。",
