        "很多新手把第一次真实下单当成高考查分,心跳全看盈亏颜色。这一步的真正目的恰恰相反:不是证明自己能赚钱,而是验证你的交易链路在现实世界里到底长什么样。你要用一笔小得可以忽略不计的钱,去观察订单怎么进市场、成交和预期差多少、费用怎么扣、对账对不对得上、自己的手会不会抖。第一次小实盘最值钱的产出,是看清真实市场会怎样扭曲你的系统、又怎样撬动你的情绪,而不是账户里多出来的那几十块钱。",
